toad_implementation.code_blueprint:
canvas {
  size: 700px 920px;
  fill: #0F1318;
  font-family: "Tenor Sans, serif";
}

>boxDark = #0F1318;
>goldFoil = #D4AF37;
>matteCard = #19202A;
>chalkWhite = #ECEBE4;

rect #outerBoxBorder {
  at: center of canvas;
  size: 540px 760px;
  fill: >matteCard;
  stroke: >goldFoil;
  stroke-width: 1px;
}

rect #innerEmbossRim {
  at: center of #outerBoxBorder;
  size: 516px 736px;
  fill: none;
  stroke: >goldFoil;
  stroke-width: 1.5px;
}

circle #crestEmboss {
  at: top center of #outerBoxBorder offset 0px 100px;
  size: 80px;
  fill: none;
  stroke: >goldFoil;
  stroke-width: 1px;
}

text #crestInitial {
  at: center of #crestEmboss;
  content: "✦";
  font-size: 32px;
  color: >goldFoil;
}

text #perfumeName {
  at: below #crestEmboss offset 64px;
  content: "L ' O M B R E   D O R É E";
  font-size: 24px;
  font-weight: 600;
  color: >goldFoil;
}

text #productType {
  at: below #perfumeName offset 14px;
  content: "EAU DE PARFUM INTENSE";
  font-size: 11px;
  color: >chalkWhite;
}

text #volumeMeta {
  at: bottom center of #outerBoxBorder offset 0px -60px;
  content: "100 ML  •  3.4 FL. OZ.  •  PARIS";
  font-size: 10px;
  font-weight: 600;
  color: >goldFoil;
}
